WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pf_d_full_cut'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '满减促销', 'kp-pf-d-full-cut', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "满减促销"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "“满 300 减 40”。不是全场八六折！这是一种阶梯式的分段折扣。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心破题"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "满减活动必须老老实实算绝对钱数！如果你买了 310 元的东西，减 40 元，实付 270 元，相当于打了 270/310 ≈ 8.7 折。但如果你买了 299 元的东西，不能减，实付 299 元，相当于没打折！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出购物篮里的商品总原价 S] --> B[用 S 除以满减的门槛(如300), 看能凑够几个满减]\nB --> C[算出总共能减去的钱数 D]\nC --> D[实际支付 = S - D]"}}]}$$ AS jsonb), NULL, '满减促销的核心考点与实战推导。', category_node.id, CAST('["数量关系", "经济利润", "满减促销"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pf_d_full_cut", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
